function commandPalette(){draw('Find your workspace',`<input id="cmdSearch" placeholder="Search tools, workflows, or capabilities…" oninput="filterCommands(this.value)" autofocus><p id="commandEmpty" role="status" hidden>No matching applications. Try “sales”, “budget”, or “project”.</p><div class="commandlist">${toolsList.map((x,i)=>`<button class="commanditem" data-command="${(x[0]+' '+x[3]).toLowerCase()}" onclick="closeDrawer();nav(${i})">${icon(productIcons[i])}<div><b>${x[0]}</b><small>${x[3]}</small></div></button>`).join('')}</div>`);setTimeout(()=>$('#cmdSearch')?.focus(),80)}function filterCommands(q){let count=0;document.querySelectorAll('[data-command]').forEach(el=>{const match=el.dataset.command.includes(q.trim().toLowerCase());el.style.display=match?'flex':'none';if(match)count++});const empty=$('#commandEmpty');if(empty)empty.hidden=count>0}

