function productGuide(){const guides=[['Start with the conversation','Attach an RFP or use the sample. Build the response with the assistant, then refine the sections in the editor.'],['Create the next conversation','Review webinar context, personalize the four-email sequence, and approve each audience segment.'],['Find the next best action','Inspect account signals, understand the score, and assign a qualified lead to the right owner.'],['Hear different perspectives','Choose your audience, submit a message, and review directional feedback before refining it.'],['Build a shared plan','Edit department budgets, explore changes with the planning assistant, and submit the plan for approval.'],['See what drives revenue','Review the quarter, inspect opportunities, and connect pipeline outcomes to the forecast.'],['Plan a balanced week','Inspect assignments and availability. Review the proposed changes before rebalancing the team.'],['Keep project work together','Move tasks through the board, discuss decisions, and keep files and stakeholders in context.'],['Connect your reports','Review the executive pulse or search the report library. Ask questions across the sample reports.'],['Test the assumptions','Change growth and conversion, compare the result with baseline, and save scenarios for review.'],['Make the investment visible','Model realized benefits, adoption, build cost, and ongoing cost. Test the result at different adoption levels.'],['Track delivery together','Open an initiative to see milestones, decisions, and project notes. Filter the portfolio by status.'],['Start with a relevant idea','Review the company signal, select a message angle, and edit the email or LinkedIn draft.']];let g=guides[current];draw(g[0],`<div class="callout">${g[1]}</div>${['Explore the sample workspace','Change an input or open a record','Review the result with your client'].map((s,i)=>`<div class="progressstep"><span class="circle">${i+1}</span><div><b>${s}</b><p>${['Use the tabs and actions to see the workflow.','Edits stay in this browser session.','AI output is simulated; no messages are sent.'][i]}</p></div>`).join('')}`)}
